content.content:
1	/* Alunix K1 Skymning — runda 3. Sex tokens + två typsnitt (scripts/scroll/NOTE.md).
2	   Aldrig restylad: .sc-stage, .sc-copy, .sc-scrim, [data-sc-*]. Allt annat härifrån. */
3	
4	:root {
5	  --sc-canvas:      #0b1424;
6	  --sc-surface:     #121c30;
7	  --sc-ink:         #f4efe6;
8	  --sc-ink-soft:    #b9c0d0;
9	  --sc-accent:      #f2c46b;
10	  --sc-accent-ink:  #1c1408;
11	
12	  --sc-font-display: "Newsreader", Georgia, serif;
13	  --sc-font-text:    "Schibsted Grotesk", system-ui, sans-serif;
14	
15	  /* egna, ej motorns sex-plus-två: mörk ink + dämpad grå för det vita klippet
16	     i akt 4-5 (house-physics: en gråton per grund, inte samma på båda). */
17	  --ink-on-white:      #17181b;
18	  --ink-soft-on-white: #5c5f68;
19	  --paper:             #ffffff;
20	  --hairline-on-white: color-mix(in oklab, var(--ink-on-white) 16%, transparent);
21	
22	  /* Utgångens mål (runda 3): bevisradens Hōrai-plate, uppmätt med
23	     shots/measure-exit-target.py mot den byggda #proof-horai-media. Platen
24	     ligger inte i bild i den sista rutan av #exit:s eget pin-intervall (den
25	     kräver ytterligare scroll förbi ingressen och första uppslaget i #proof
26	     — mätt, inte gissat: se NOTES.md) — målet är därför platens naturliga
27	     viloläge, centrerat i viewporten, dit krympningen siktar. */
28	  --exit-tx: 74.5%;
29	  --exit-ty: 50.0%;
30	  --exit-sx: 0.321;
31	  --exit-sy: 0.386;
32	}
33	
34	html, body { overflow-x: clip; }
35	
36	/* ------------------------------------------------------------- toppbar -- */
37	.topbar {
38	  position: fixed; inset: 0 0 auto 0; z-index: 80;
39	  display: flex; align-items: center; justify-content: space-between;
40	  padding: clamp(1rem, 3vw, 1.75rem) clamp(1.25rem, 4vw, 2.5rem);
41	  pointer-events: none;
42	}
43	/* Two static gradient layers, cross-fading by opacity only: swapping the
44	   gradient stops themselves (as one layer previously did) is an instant snap
45	   no matter what transitions, since only opacity/transform truly interpolate. */
46	.topbar::before, .topbar::after {
47	  content: ""; position: absolute; inset: 0; height: 220%; z-index: -1;
48	  transition: opacity 300ms var(--sc-ease-out, ease);
49	}
50	.topbar::before {
51	  background: linear-gradient(180deg, rgba(6,10,18,0.68) 0%, rgba(6,10,18,0.2) 55%, transparent 82%);
52	  opacity: 0.95;
53	}
54	.topbar.is-dim::before { opacity: 0; }
55	.topbar::after {
56	  background: linear-gradient(180deg, rgba(4,6,10,0.82) 0%, rgba(4,6,10,0.82) 55%, transparent 100%);
57	  opacity: 0;
58	}
59	.topbar.is-dim::after { opacity: 1; }
60	
61	/* Paper zone (akt 4-5, white ground): flip to ink-on-paper with a hairline,
62	   drop the dark scrim entirely. Toggled by script.js's section observer. */
63	.topbar.zone-light { background: color-mix(in oklab, var(--paper) 92%, transparent); border-bottom: 1px solid var(--hairline-on-white); }
64	.topbar.zone-light::before, .topbar.zone-light::after { opacity: 0 !important; }
65	.topbar.zone-light .topbar__contact { color: var(--ink-on-white); border-bottom-color: color-mix(in oklab, var(--ink-on-white) 40%, transparent); }
66	.topbar.zone-light .topbar__label { color: var(--ink-soft-on-white); }
67	.topbar.zone-light .topbar__mark-img--white { opacity: 0; }
68	.topbar.zone-light .topbar__mark-img--black { opacity: 1; }
69	
70	.topbar__mark { pointer-events: auto; line-height: 0; position: relative; display: block; width: 112px; height: 22px; }
71	.topbar__mark-img { height: 20px; width: auto; filter: drop-shadow(0 1px 3px rgba(0,0,0,0.4)); position: absolute; inset: 0; transition: opacity 300ms var(--sc-ease-out, ease); }
72	.topbar__mark-img--black { opacity: 0; filter: none; }
73	.topbar__contact {
74	  pointer-events: auto;
75	  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
76	  color: var(--sc-ink); text-decoration: none;
77	  border-bottom: 1px solid color-mix(in oklab, var(--sc-ink) 40%, transparent);
78	  transition: color 150ms ease, border-color 150ms ease;
79	  /* scroll_verify.py mätte 3.66:1 (golv 4.5) mot skymningsfotots ljusa
80	     himmel: den bakomliggande skrimmen räcker inte överallt. En mjuk
81	     textskugga håller kontrasten även över de ljusaste molnen, utan att
82	     ändra skrimmen som täcker resten av bilden. */
83	  text-shadow: 0 1px 4px rgba(0,0,0,0.7), 0 1px 1px rgba(0,0,0,0.5);
84	}
85	.topbar.zone-light .topbar__contact { text-shadow: none; }
86	.topbar__contact:hover { border-bottom-color: var(--sc-accent); color: var(--sc-accent); }
87	.topbar__label {
88	  font-family: var(--sc-font-text); font-size: var(--sc-t-xs);
89	  letter-spacing: var(--sc-track-wide); text-transform: uppercase;
90	  color: var(--sc-ink-soft); opacity: 0; white-space: nowrap;
91	  position: absolute; left: 50%; translate: -50% 0;
92	  transition: color 300ms var(--sc-ease-out, ease);
93	}
94	@media (max-width: 860px) { .topbar__label { display: none; } }
95	
96	/* ------------------------------------------------------- reservläge/motion toggle -- */
97	.motion-only { display: none; }
98	html.motion .motion-only { display: block; }
99	html.motion .rm-only { display: none; }
100	.rm-only { display: block; }
101	
102	/* ------------------------------------------------------------- akt 1-3 hero -- */
103	#hero [data-sc-stage] { background: var(--sc-canvas); }
104	
105	.window-glow, .window-fill, .window-glass {
106	  position: absolute; left: 0; top: 0; width: 0; height: 0;
107	  opacity: 0; z-index: 2; pointer-events: none;
108	}
109	.window-glow {
110	  background: radial-gradient(closest-side, color-mix(in oklab, var(--sc-accent) 85%, white) 0%, color-mix(in oklab, var(--sc-accent) 40%, transparent) 60%, transparent 100%);
111	}
112	.window-fill { object-fit: cover; display: block; }
113	.window-glass { overflow: hidden; mix-blend-mode: multiply; }
114	.window-glass__canvas { width: 100%; height: 100%; display: block; }
115	
116	.hero-copy {
117	  filter: blur(calc(min(var(--sc-p, 0), 0.3) * 46.67px));
118	}
119	.hero-title {
120	  font-weight: 300; font-size: clamp(2.2rem, 3.4rem + 1.6vw, 5.5rem);
121	  line-height: 1.05; letter-spacing: -0.01em; color: var(--sc-ink);
122	  max-width: 16ch;
123	}
124	.accent-u { text-decoration: underline; text-decoration-color: var(--sc-accent); text-decoration-thickness: 2px; text-underline-offset: 0.1em; }
125	/* scroll_verify.py flaggade denna som en cue som aldrig når full opacitet
126	   (peak 0.86) -- opaciteten var en smaksak (en "tystare" underrad), inte en
127	   avsiktlig cue-gräns, och håller inte isär de två. Dämpningen sker nu genom
128	   en egen ton i stället, så cuen faktiskt kan nå 1. */
129	.hero-sub { color: var(--sc-ink); margin-top: var(--sc-4); font-size: var(--sc-t-lg); }
130	
131	.site-names {
132	  position: absolute; left: var(--sc-gutter); bottom: clamp(1.25rem, 4vh, 2.5rem);
133	  z-index: 5; margin: 0;
134	  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
135	  letter-spacing: var(--sc-track-normal); color: var(--sc-ink-soft);
136	}
137	.site-names--static { position: static; margin-top: var(--sc-6); color: var(--sc-ink-soft); }
138	
139	/* --------------------------------------------------------- akt 3 pin/ram -- */
140	.reveal-stage {
141	  background: #05070c;
142	  /* crossfade progress 0..1 across the opening 35% of the pin, and a
143	     triangular bump (4t(1-t)) that peaks at its midpoint: a static
144	     screenshot and a live-rendered iframe never align pixel-perfectly, and a
145	     brief blur bridges that mismatch instead of showing two overlapping
146	     images (emil-design-eng: "use blur to mask imperfect transitions"). */
147	  --xfade: calc(min(var(--sc-p, 0), 0.35) / 0.35);
148	  --xfade-blur: calc(4 * var(--xfade) * (1 - var(--xfade)) * 6px);
149	}
150	.reveal-frozen {
151	  position: absolute; inset: 0; z-index: 3; pointer-events: none;
152	  transform-origin: 50.3% 51.5%;
153	  transform: scale(calc(1 + var(--xfade) * 0.282));
154	  opacity: calc(1 - var(--xfade));
155	  filter: blur(var(--xfade-blur));
156	}
157	.reveal-frozen__photo { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
158	/* Bugg 1 (runda 3): detta lager saknade en klippväg och lade en HEL
159	   rektangel av Hōrai-skärmbilden över hela fotot redan innan #reveal-akten
160	   ens börjat scrollas (synlig som "en remsa av den levande ramen" när #hero
161	   släpper sitt pin-läge och #reveal:s overslag skymtar i botten av
162	   viewporten, ett normalt beteende hos position:sticky-kedjan). script.js
163	   positionerar/klipper nu #reveal-frozen-mask till exakt samma fönsterform
164	   som hero:s sista ruta, en gång vid inläsning. */
165	.reveal-frozen__mask { position: absolute; overflow: hidden; }
166	.reveal-frozen__horai, .reveal-frozen__glass { position: absolute; inset: 0; width: 100%; height: 100%; }
167	.reveal-frozen__horai { object-fit: cover; }
168	.reveal-frozen__glass { mix-blend-mode: multiply; background: linear-gradient(180deg, rgba(255,224,170,0.25), rgba(20,14,8,0.35)); }
169	.reveal-frame-slot { position: absolute; inset: 0; z-index: 2; }
170	.reveal-frame-slot iframe {
171	  position: absolute; inset: 0; width: 100%; height: 100%; border: 0;
172	  opacity: var(--xfade);
173	  filter: blur(var(--xfade-blur));
174	}
175	
176	/* -------------------------------------------------------------- akt 4a exit -- */
177	.exit-stage { background: var(--sc-canvas); overflow: clip; }
178	.exit-sweep { position: absolute; inset: 0; background: var(--paper); z-index: 4; }
179	.exit-frame-wrap {
180	  position: absolute; inset: 0; z-index: 2;
181	  transform-origin: var(--exit-tx) var(--exit-ty);
182	  /* Icke-uniform skala (sx/sy separat) mot den uppmätta rektangeln: bilden
183	     INUTI omslaget använder object-fit:cover, så den kompenserar löpande för
184	     omslagets skiftande proportioner under resan i stället för att sträckas. */
185	  transform: scale(calc(1 - min(var(--sc-p, 0), 0.7)/0.7 * (1 - var(--exit-sx))),
186	                    calc(1 - min(var(--sc-p, 0), 0.7)/0.7 * (1 - var(--exit-sy))));
187	}
188	.exit-frame { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
189	.exit-copy { position: absolute; z-index: 5; left: var(--sc-gutter); right: var(--sc-gutter); bottom: clamp(2.5rem, 12vh, 6rem); }
190	.exit-heading {
191	  max-width: 20ch; font-weight: 600; color: var(--ink-on-white);
192	  font-size: clamp(2rem, 1.4rem + 3.6vw, 4.5rem); line-height: 1.16;
193	}
194	/* Ä:s prickar sitter ovanför versalhöjden och kapas av motorns
195	   .sc-split--line-mask (overflow:hidden) vid en trång line-height -- exakt
196	   samma fel r6 en gång rättade ("VARUMÄRKE" tappade prickarna). Fixen är
197	   densamma: luft ovanför masken, aldrig overflow borttaget (motorklassen
198	   rörs inte). */
199	.exit-heading .sc-split--line { padding-top: 0.16em; margin-top: -0.16em; }
200	.exit-lede { font-family: var(--sc-font-text); font-size: var(--sc-t-lg); color: var(--ink-soft-on-white); margin-top: var(--sc-4); max-width: 40ch; }
201	.exit-heading--static, .exit-lede--static { position: static; color: var(--ink-on-white); max-width: 24ch; }
202	.exit-lede--static { color: var(--ink-soft-on-white); margin-top: var(--sc-3); }
203	
204	/* ---------------------------------------------------------- akt 4b bevisrad -- */
205	.proof-section { background: var(--paper); padding-block: var(--sc-section); }
206	/* Bildsidan bär 7 kolumner, texten 5 (BRIEF § "Bygg raden"): bilden är den
207	   tyngre, redovisande sidan; texten är etiketten bredvid. */
208	.proof-row { display: grid; grid-template-columns: 7fr 5fr; gap: clamp(1.5rem, 4vw, var(--sc-8)); align-items: center; }
209	.proof-row + .proof-row { margin-top: clamp(3rem, 8vw, var(--sc-10)); }
210	.proof-row--reverse { grid-template-columns: 5fr 7fr; }
211	.proof-row__media { margin: 0; grid-row: 1; }
212	.proof-row--reverse .proof-row__media { grid-column: 2; }
213	.proof-row__media img { width: 100%; display: block; aspect-ratio: 4/3; object-fit: cover; }
214	.proof-row__media--left, .proof-row__media--right { margin-top: 0; }
215	.proof-row:not(.proof-row--reverse) .proof-row__text { margin-top: clamp(1.5rem, 6vh, 6rem); }
216	.proof-row--reverse .proof-row__media { margin-top: clamp(1.5rem, 6vh, 6rem); }
217	.proof-row__num { font-family: var(--sc-font-text); font-size: var(--sc-t-sm); color: var(--sc-accent-ink); background: color-mix(in oklab, var(--sc-accent) 70%, transparent); display: inline-block; padding: 0.15em 0.55em; letter-spacing: var(--sc-track-wide); margin: 0 0 var(--sc-3); }
218	.proof-row__title { font-weight: 500; font-size: var(--sc-t-3xl); color: var(--ink-on-white); margin: 0; }
219	.proof-row__body { color: var(--ink-soft-on-white); font-size: var(--sc-t-base); margin-top: var(--sc-3); max-width: 36ch; }
220	.proof-row__site { font-family: var(--sc-font-text); font-size: var(--sc-t-xs); letter-spacing: var(--sc-track-wide); text-transform: uppercase; color: var(--ink-soft-on-white); margin-top: var(--sc-4); }
221	
222	/* ------------------------------------------------------------ akt 5 liggare -- */
223	.ledger-section { background: var(--paper); padding-block: var(--sc-section); }
224	.ledger-heading { color: var(--ink-on-white); font-weight: 300; font-size: clamp(2rem, 1.5rem + 3vw, 4rem); margin: 0 0 var(--sc-8); }
225	.ledger-list { border-top: 1px solid var(--hairline-on-white); }
226	.ledger-row {
227	  position: relative; display: grid; grid-template-columns: 1fr auto; align-items: baseline;
228	  gap: var(--sc-4); padding-block: clamp(1.5rem, 4vw, var(--sc-7));
229	  border-bottom: 1px solid var(--hairline-on-white);
230	}
231	.ledger-row__hairline {
232	  position: absolute; left: 0; right: 0; bottom: -1px; height: 1px; margin: 0;
233	  background: var(--ink-on-white); transform-origin: left center;
234	  /* Ritas i takt med scrollen: --sc-p publiceras på #ledger (flow-akt),
235	     varje rad har sitt eget fönster via en index-offset (--row-i). */
236	  transform: scaleX(clamp(0, (var(--sc-p, 0) - 0.15 - var(--row-i, 0) * 0.18) / 0.22, 1));
237	}
238	.ledger-row__desc { color: var(--ink-soft-on-white); font-size: var(--sc-t-base); max-width: 46ch; margin: 0; }
239	.ledger-row__price { font-family: var(--sc-font-display); font-weight: 500; font-size: clamp(1.5rem, 1.1rem + 2vw, 3rem); color: var(--ink-on-white); text-align: right; white-space: nowrap; margin: 0; font-variant-numeric: tabular-nums; }
240	.ledger-list--static .ledger-row__hairline--static { transform: scaleX(1); }
241	
242	/* --------------------------------------------------------------- akt 6 landning -- */
243	.landing-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; display: flex; align-items: flex-end; background: var(--sc-canvas); }
244	.landing-night { position: absolute; inset: 0; z-index: 0; clip-path: inset(calc(50% - min(var(--sc-p, 0), 1) * 50%) 0 calc(50% - min(var(--sc-p, 0), 1) * 50%) 0); }
245	.landing-night__img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
246	/* scroll_verify.py mätte kontakt@alunix.se ner mot 1.53:1 (golv 3.0) mot
247	   nattfotots ljusa partier (upplysta fasader, torn). En skrim bara där
248	   texten sitter, aldrig hela bilden. */
249	.landing-scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(5,8,14,0.92) 0%, rgba(5,8,14,0.55) 45%, transparent 78%); }
250	.landing-copy { position: relative; z-index: 2; padding-bottom: clamp(2.5rem, 8vh, 5rem); width: 100%; }
251	.landing-mailto { font-family: var(--sc-font-display); font-weight: 300; font-size: clamp(2rem, 1.3rem + 4vw, 5rem); color: var(--sc-ink); text-decoration: none; border-bottom: 2px solid color-mix(in oklab, var(--sc-ink) 40%, transparent); }
252	.landing-mailto:hover { border-bottom-color: var(--sc-accent); color: var(--sc-accent); transition: color 200ms ease, border-color 200ms ease; }
253	.landing-address { font-size: var(--sc-t-lg); color: var(--sc-ink-soft); margin-top: var(--sc-5); max-width: 42ch; }
254	.landing-credits { font-family: var(--sc-font-text); font-size: var(--sc-t-xs); color: var(--sc-ink-soft); margin-top: var(--sc-8); }
255	.landing-copy--static { padding: clamp(1.5rem,5vw,3rem); position: static; }
256	
257	/* ---------------------------------------------------------- reservläge -- */
258	.rm-only { background: var(--sc-canvas); }
259	.rm-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; }
260	.rm-section--hero { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(1.5rem,5vw,3rem); }
261	.rm-section__bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
262	.rm-section__scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(6,10,18,0.85) 0%, rgba(6,10,18,0.35) 45%, transparent 70%); }
263	.rm-hero-copy { position: relative; z-index: 2; max-width: 40rem; }
264	.rm-section--window { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-5); background: #05070c; }
265	.rm-window-stage { position: relative; width: min(92vw, 1200px); aspect-ratio: 3 / 2; overflow: clip; border-radius: 2px; }
266	.rm-window-stage__photo, .rm-window-mask__fill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
267	.rm-window-mask { position: absolute; z-index: 2; overflow: hidden; }
268	.rm-window-mask__glass { position: absolute; inset: 0; mix-blend-mode: multiply; background: linear-gradient(180deg, rgba(255,224,170,0.22), rgba(20,14,8,0.3)); }
269	.rm-section--frame { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-4); background: #05070c; }
270	.rm-frame-slot { width: min(94vw, 1400px); aspect-ratio: 16 / 9; border: 1px solid color-mix(in oklab, var(--sc-ink) 16%, transparent); }
271	.rm-frame-slot iframe { width: 100%; height: 100%; border: 0; display: block; }
272	.rm-caption { font-family: var(--sc-font-text); font-size: var(--sc-t-sm); color: var(--sc-ink-soft); text-align: center; margin: 0; }
273	.rm-section--proof { background: var(--paper); display: flex; flex-direction: column; justify-content: center; padding: clamp(1.5rem,6vw,4rem); gap: var(--sc-7); }
274	.rm-proof-rows { display: flex; flex-direction: column; gap: var(--sc-8); }
275	.rm-proof-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--sc-6); align-items: center; }
276	.rm-proof-row img { width: 100%; aspect-ratio: 4/3; object-fit: cover; display: block; }
277	.rm-section--ledger { background: var(--paper); display: flex; flex-direction: column; justify-content: center; padding: clamp(1.5rem,6vw,4rem); }
278	.rm-section--landing { display: flex; align-items: flex-end; }
279	
280	@media (max-width: 860px) {
281	  .hero-title { max-width: 14ch; }
282	  .exit-heading, .exit-heading--static { max-width: none; }
283	  .proof-row, .proof-row--reverse { grid-template-columns: 1fr; }
284	  .proof-row--reverse .proof-row__media { grid-column: 1; }
285	  .proof-row:not(.proof-row--reverse) .proof-row__text,
286	  .proof-row--reverse .proof-row__media { margin-top: var(--sc-5); }
287	  .rm-proof-row { grid-template-columns: 1fr; }
288	  .ledger-row { grid-template-columns: 1fr; }
289	  .ledger-row__price { text-align: left; }
290	}
