1	/* Alunix K1 Skymning — runda 3. Bespoke fönstermask (F-010), läser --sc-p och
2	   assets/push/window-track.json. Motorn (scrollcraft.js) rörs aldrig här. */
3	(function () {
4	  'use strict';
5	
6	  var NATURAL_W = 1440, NATURAL_H = 960;
7	  var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
8	
9	  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
10	  function smooth(x) { x = clamp01(x); return x * x * (3 - 2 * x); }
11	
12	  function coverBox(boxW, boxH, natW, natH) {
13	    var scale = Math.max(boxW / natW, boxH / natH);
14	    var drawnW = natW * scale, drawnH = natH * scale;
15	    return { scale: scale, offX: (boxW - drawnW) / 2, offY: (boxH - drawnH) / 2 };
16	  }
17	
18	  function frameBox(kf, boxW, boxH) {
19	    var c = coverBox(boxW, boxH, NATURAL_W, NATURAL_H);
20	    var px = c.offX + kf.x * NATURAL_W * c.scale;
21	    var py = c.offY + kf.y * NATURAL_H * c.scale;
22	    var pw = kf.w * NATURAL_W * c.scale;
23	    var ph = kf.h * NATURAL_H * c.scale;
24	    return { px: px, py: py, pw: pw, ph: ph, archH: kf.arch * ph };
25	  }
26	
27	  function pathFor(box) {
28	    var pw = box.pw, ph = box.ph, a = box.archH;
29	    return 'path("M0,' + a.toFixed(1) + ' L0,' + ph.toFixed(1) + ' L' + pw.toFixed(1) + ',' + ph.toFixed(1) +
30	      ' L' + pw.toFixed(1) + ',' + a.toFixed(1) + ' A' + (pw / 2).toFixed(1) + ',' + a.toFixed(1) +
31	      ' 0 0 0 0,' + a.toFixed(1) + ' Z")';
32	  }
33	
34	  function interpTrack(frame, keys) {
35	    if (frame <= keys[0].frame) return keys[0];
36	    if (frame >= keys[keys.length - 1].frame) return keys[keys.length - 1];
37	    for (var i = 0; i < keys.length - 1; i++) {
38	      var a = keys[i], b = keys[i + 1];
39	      if (frame >= a.frame && frame <= b.frame) {
40	        var t = (frame - a.frame) / (b.frame - a.frame);
41	        return {
42	          x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t,
43	          w: a.w + (b.w - a.w) * t, h: a.h + (b.h - a.h) * t,
44	          arch: a.arch + (b.arch - a.arch) * t
45	        };
46	      }
47	    }
48	    return keys[keys.length - 1];
49	  }
50	
51	  function makeHoraiFrame(cls, title) {
52	    var f = document.createElement('iframe');
53	    f.className = cls;
54	    f.title = title;
55	    f.loading = 'eager';
56	    f.src = '/sites/horai.html';
57	    return f;
58	  }
59	
60	  // ---- reduced motion: render the one static formed frame, mount nothing.
61	  // Ramen skapas här i JS (bugg 3, runda 3): en hårdkodad <iframe src> i
62	  // statisk HTML laddar Hōrai även när den akten aldrig blir aktiv, vilket
63	  // gav TVÅ samtidiga Hōrai-iframes i rörelseläge. Nu finns bara en, skapad
64	  // av den gren som faktiskt körs. ----
65	  function renderStatic(track) {
66	    var stage = document.getElementById('rm-window-stage');
67	    var photo = document.getElementById('rm-window-photo');
68	    var mask = document.getElementById('rm-window-mask');
69	    if (stage && photo && mask) {
70	      var apply = function () {
71	        var box = frameBox(track.keys[track.keys.length - 1], stage.clientWidth, stage.clientHeight);
72	        mask.style.left = box.px + 'px'; mask.style.top = box.py + 'px';
73	        mask.style.width = box.pw + 'px'; mask.style.height = box.ph + 'px';
74	        mask.style.clipPath = pathFor(box);
75	      };
76	      if (photo.complete) apply(); else photo.addEventListener('load', apply, { once: true });
77	      addEventListener('resize', apply, { passive: true });
78	    }
79	
80	    var slot = document.getElementById('rm-frame-slot');
81	    if (slot) slot.appendChild(makeHoraiFrame('rm-frame', 'Hōrai, exempelsajt'));
82	  }
83	
