/* Alunix K1 Skymning — runda 3. Bespoke fönstermask (F-010), läser --sc-p och
   assets/push/window-track.json. Motorn (scrollcraft.js) rörs aldrig här. */
(function () {
  'use strict';

  var NATURAL_W = 1440, NATURAL_H = 960;
  var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
  function smooth(x) { x = clamp01(x); return x * x * (3 - 2 * x); }

  function coverBox(boxW, boxH, natW, natH) {
    var scale = Math.max(boxW / natW, boxH / natH);
    var drawnW = natW * scale, drawnH = natH * scale;
    return { scale: scale, offX: (boxW - drawnW) / 2, offY: (boxH - drawnH) / 2 };
  }

  function frameBox(kf, boxW, boxH) {
    var c = coverBox(boxW, boxH, NATURAL_W, NATURAL_H);
    var px = c.offX + kf.x * NATURAL_W * c.scale;
    var py = c.offY + kf.y * NATURAL_H * c.scale;
    var pw = kf.w * NATURAL_W * c.scale;
    var ph = kf.h * NATURAL_H * c.scale;
    return { px: px, py: py, pw: pw, ph: ph, archH: kf.arch * ph };
  }

  function pathFor(box) {
    var pw = box.pw, ph = box.ph, a = box.archH;
    return 'path("M0,' + a.toFixed(1) + ' L0,' + ph.toFixed(1) + ' L' + pw.toFixed(1) + ',' + ph.toFixed(1) +
      ' L' + pw.toFixed(1) + ',' + a.toFixed(1) + ' A' + (pw / 2).toFixed(1) + ',' + a.toFixed(1) +
      ' 0 0 0 0,' + a.toFixed(1) + ' Z")';
  }

  function interpTrack(frame, keys) {
    if (frame <= keys[0].frame) return keys[0];
    if (frame >= keys[keys.length - 1].frame) return keys[keys.length - 1];
    for (var i = 0; i < keys.length - 1; i++) {
      var a = keys[i], b = keys[i + 1];
      if (frame >= a.frame && frame <= b.frame) {
        var t = (frame - a.frame) / (b.frame - a.frame);
        return {
          x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t,
          w: a.w + (b.w - a.w) * t, h: a.h + (b.h - a.h) * t,
          arch: a.arch + (b.arch - a.arch) * t
        };
      }
    }
    return keys[keys.length - 1];
  }

  function makeHoraiFrame(cls, title) {
    var f = document.createElement('iframe');
    f.className = cls;
    f.title = title;
    f.loading = 'eager';
    f.src = '/sites/horai.html';
    return f;
  }

  // ---- reduced motion: render the one static formed frame, mount nothing.
  // Ramen skapas här i JS (bugg 3, runda 3): en hårdkodad <iframe src> i
  // statisk HTML laddar Hōrai även när den akten aldrig blir aktiv, vilket
  // gav TVÅ samtidiga Hōrai-iframes i rörelseläge. Nu finns bara en, skapad
  // av den gren som faktiskt körs. ----
  function renderStatic(track) {
    var stage = document.getElementById('rm-window-stage');
    var photo = document.getElementById('rm-window-photo');
    var mask = document.getElementById('rm-window-mask');
    if (stage && photo && mask) {
      var apply = function () {
        var box = frameBox(track.keys[track.keys.length - 1], stage.clientWidth, stage.clientHeight);
        mask.style.left = box.px + 'px'; mask.style.top = box.py + 'px';
        mask.style.width = box.pw + 'px'; mask.style.height = box.ph + 'px';
        mask.style.clipPath = pathFor(box);
      };
      if (photo.complete) apply(); else photo.addEventListener('load', apply, { once: true });
      addEventListener('resize', apply, { passive: true });
    }

    var slot = document.getElementById('rm-frame-slot');
    if (slot) slot.appendChild(makeHoraiFrame('rm-frame', 'Hōrai, exempelsajt'));
  }

  // ---- motion build: mount the engine, then drive the bespoke window mask ----
  function startMotion(track) {
    document.documentElement.classList.add('motion');
    var api = ScrollCraft.mount(document.body);

    var heroAct = null, revealAct = null, exitAct = null, ledgerAct = null;
    for (var i = 0; i < api.acts.length; i++) {
      var id = api.acts[i].el.id;
      if (id === 'hero') heroAct = api.acts[i];
      if (id === 'reveal') revealAct = api.acts[i];
      if (id === 'exit') exitAct = api.acts[i];
      if (id === 'ledger') ledgerAct = api.acts[i];
    }

    // Bugg 1 (runda 3): #reveal-frozen-mask hade ingen klippväg tidigare och
    // visade Hōrai-skärmbilden som en hel rektangel redan innan #reveal-akten
    // scrollats till, synlig i botten av viewporten under #hero:s normala
    // sticky-till-vanligt-flöde-övergång. Masken beräknas en gång mot
    // #reveal:s egen stage (samma geometri som hero:s sista ruta), så vad som
    // helst som skymtar av #reveal i vila är redan format som fönstret,
    // aldrig en platt ruta.
    var frozenMask = document.getElementById('reveal-frozen-mask');
    if (frozenMask && revealAct && revealAct.stage) {
      var applyFrozenMask = function () {
        var box = frameBox(track.keys[track.keys.length - 1], revealAct.stage.clientWidth, revealAct.stage.clientHeight);
        frozenMask.style.left = box.px + 'px'; frozenMask.style.top = box.py + 'px';
        frozenMask.style.width = box.pw + 'px'; frozenMask.style.height = box.ph + 'px';
        frozenMask.style.clipPath = pathFor(box);
      };
      applyFrozenMask();
      addEventListener('resize', applyFrozenMask, { passive: true });
    }

    // Ramen skapas i JS, aldrig med src i statisk HTML (bugg 3). Läggs in
    // dolt (visibility) och avslöjas bara av applyReveal() nedan när
    // korstoningen faktiskt är igång, som ett andra skyddsnät utöver
    // CSS-opaciteten (bugg 1 visade att ett lager kan bli synligt av skäl
    // opaciteten ensam inte skyddar mot).
    var revealFrame = makeHoraiFrame('', 'Hōrai, exempelsajt');
    revealFrame.style.visibility = 'hidden';
    var frameSlot = document.getElementById('reveal-frame-slot');
    if (frameSlot) frameSlot.appendChild(revealFrame);

    var glow = document.querySelector('.window-glow');
    var fill = document.querySelector('.window-fill');
    var glassWrap = document.querySelector('.window-glass');
    var glassCanvas = document.querySelector('.window-glass__canvas');
    var gctx = glassCanvas && glassCanvas.getContext('2d');
    var topbarLabel = document.getElementById('topbar-label');
    var topbar = document.getElementById('topbar');
    var lastDrawnIdx = -1;

    function applyHero() {
      if (!heroAct || !heroAct.stage) return;
      var boxW = heroAct.stage.clientWidth, boxH = heroAct.stage.clientHeight;
      var idx = Math.min(99, Math.max(0, Math.round(heroAct.p * 99)));
      var frame = idx + 1;

      if (frame < 58) {
        glow.style.opacity = 0; fill.style.opacity = 0; glassWrap.style.opacity = 0;
      } else {
        var kf = interpTrack(frame, track.keys);
        var box = frameBox(kf, boxW, boxH);
        var path = pathFor(box);
        [glow, fill, glassWrap].forEach(function (el) {
          el.style.left = box.px + 'px'; el.style.top = box.py + 'px';
          el.style.width = box.pw + 'px'; el.style.height = box.ph + 'px';
          el.style.clipPath = path;
        });
        var fillT = smooth((frame - track.first_frame_with_horai) / 6);
        fill.style.opacity = fillT.toFixed(3);
        glassWrap.style.opacity = (0.15 + fillT * 0.4).toFixed(3);
        glow.style.opacity = (1 - fillT * 0.8).toFixed(3);

        if (idx !== lastDrawnIdx && frame >= track.first_frame_with_horai && heroAct.seq) {
          var img = heroAct.seq.frames[idx];
          if (img && img.complete && img.naturalWidth) {
            var sx = kf.x * NATURAL_W, sy = kf.y * NATURAL_H, sw = kf.w * NATURAL_W, sh = kf.h * NATURAL_H;
            var dpr = Math.min(devicePixelRatio || 1, 2);
            glassCanvas.width = Math.max(1, Math.round(box.pw * dpr));
            glassCanvas.height = Math.max(1, Math.round(box.ph * dpr));
            gctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            gctx.drawImage(img, sx, sy, sw, sh, 0, 0, box.pw, box.ph);
          }
          lastDrawnIdx = idx;
        }
      }
    }

    function applyReveal() {
      if (!revealAct) return;
      var p = revealAct.p;
      // Andra skyddsnätet mot bugg 1: ramen syns aldrig förrän korstoningen
      // faktiskt passerat ett litet tröskelvärde, oavsett vad CSS-opaciteten
      // råkar räkna ut under en övergångsruta.
      revealFrame.style.visibility = (revealAct.live && p > 0.02) ? 'visible' : 'hidden';

      var on = revealAct.live && p > 0.3;
      if (topbar) topbar.classList.toggle('is-dim', !!on);
      if (topbarLabel) {
        var vis = 0;
        if (p >= 0.42 && p <= 0.94) {
          var win = 0.94 - 0.42;
          var inEnd = 0.42 + win * 0.25, outStart = 0.94 - win * 0.25;
          if (p < inEnd) vis = smooth((p - 0.42) / (inEnd - 0.42));
          else if (p <= outStart) vis = 1;
          else vis = smooth(1 - (p - outStart) / (0.94 - outStart));
        }
        topbarLabel.style.opacity = revealAct.live ? vis.toFixed(3) : 0;
      }
    }

    function loop() {
      applyHero();
      applyReveal();
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);

    // ---- toppbarens zon: papper med hårlinje över vitt, mörkt över foto/natt ----
    var zoneEls = document.querySelectorAll('[data-topbar-zone]');
    if ('IntersectionObserver' in window && zoneEls.length) {
      var zoneIO = new IntersectionObserver(function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
            var zone = e.target.getAttribute('data-topbar-zone');
            topbar.classList.toggle('zone-light', zone === 'light');
          }
        });
      }, { rootMargin: '-1px 0px -99% 0px', threshold: 0 });
      zoneEls.forEach(function (el) { zoneIO.observe(el); });
    }

    // ---- ?preview= : force a formed state for screenshotting, no scroll.
    // Bugg 2 (runda 3): ett hopp rakt till ruta 100 innan bildsekvensen hunnit
    // ladda klart lämnade canvasen svart (drawSeq() ritar bara när img.complete
    // är sant). Väntar nu in seq.loaded === seq.count (med en kort timeout som
    // reserv) innan scroll+read(). ----
    var params = new URLSearchParams(location.search);
    var preview = params.get('preview');
    if (preview) {
      var targets = { window: ['hero', 0.999], horai: ['reveal', 0.65], exit: ['exit', 0.6], ledger: ['ledger', 0.85] };
      var t = targets[preview];
      if (t) {
        var runPreview = function () {
          var act = null;
          for (var j = 0; j < api.acts.length; j++) if (api.acts[j].el.id === t[0]) act = api.acts[j];
          if (!act) return;
          var y = act.pinned ? act.top + (act.height - innerHeight) * t[1]
                              : act.top + act.height * t[1] - innerHeight * 0.4;
          scrollTo({ top: Math.max(0, y), left: 0, behavior: 'instant' });
          api.read();
        };
        if (heroAct && heroAct.seq) {
          var waited = 0;
          (function waitForFrames() {
            if (heroAct.seq.loaded >= heroAct.seq.count || waited > 4000) { runPreview(); return; }
            waited += 60;
            setTimeout(waitForFrames, 60);
          })();
        } else {
          runPreview();
        }
      }
    }
  }

  fetch('assets/push/window-track.json')
    .then(function (r) { return r.json(); })
    .then(function (track) {
      if (reduce) renderStatic(track);
      else startMotion(track);
    })
    .catch(function () { /* geometry unavailable: base photo frames still read fine without the mask */ });
})();

