tool_use_result.originalFile:
/* Alunix K1 Skymning — runda 3. Sex tokens + två typsnitt (scripts/scroll/NOTE.md).
   Aldrig restylad: .sc-stage, .sc-copy, .sc-scrim, [data-sc-*]. Allt annat härifrån. */

:root {
  --sc-canvas:      #0b1424;
  --sc-surface:     #121c30;
  --sc-ink:         #f4efe6;
  --sc-ink-soft:    #b9c0d0;
  --sc-accent:      #f2c46b;
  --sc-accent-ink:  #1c1408;

  --sc-font-display: "Newsreader", Georgia, serif;
  --sc-font-text:    "Schibsted Grotesk", system-ui, sans-serif;

  /* egna, ej motorns sex-plus-två: mörk ink + dämpad grå för det vita klippet
     i akt 4-5 (house-physics: en gråton per grund, inte samma på båda). */
  --ink-on-white:      #17181b;
  --ink-soft-on-white: #5c5f68;
  --paper:             #ffffff;
  --hairline-on-white: color-mix(in oklab, var(--ink-on-white) 16%, transparent);

  /* Utgångens mål (runda 3): bevisradens Hōrai-plate, uppmätt med
     shots/measure-exit-target.py mot den byggda #proof-horai-media. Platen
     ligger inte i bild i den sista rutan av #exit:s eget pin-intervall (den
     kräver ytterligare scroll förbi ingressen och första uppslaget i #proof
     — mätt, inte gissat: se NOTES.md) — målet är därför platens naturliga
     viloläge, centrerat i viewporten, dit krympningen siktar. */
  --exit-tx: 74.5%;
  --exit-ty: 50.0%;
  --exit-sx: 0.321;
  --exit-sy: 0.386;
}

html, body { overflow-x: clip; }

/* ------------------------------------------------------------- toppbar -- */
.topbar {
  position: fixed; inset: 0 0 auto 0; z-index: 80;
  display: flex; align-items: center; justify-content: space-between;
  padding: clamp(1rem, 3vw, 1.75rem) clamp(1.25rem, 4vw, 2.5rem);
  pointer-events: none;
}
/* Two static gradient layers, cross-fading by opacity only: swapping the
   gradient stops themselves (as one layer previously did) is an instant snap
   no matter what transitions, since only opacity/transform truly interpolate. */
.topbar::before, .topbar::after {
  content: ""; position: absolute; inset: 0; height: 220%; z-index: -1;
  transition: opacity 300ms var(--sc-ease-out, ease);
}
.topbar::before {
  background: linear-gradient(180deg, rgba(6,10,18,0.68) 0%, rgba(6,10,18,0.2) 55%, transparent 82%);
  opacity: 0.95;
}
.topbar.is-dim::before { opacity: 0; }
.topbar::after {
  background: linear-gradient(180deg, rgba(4,6,10,0.82) 0%, rgba(4,6,10,0.82) 55%, transparent 100%);
  opacity: 0;
}
.topbar.is-dim::after { opacity: 1; }

/* Paper zone (akt 4-5, white ground): flip to ink-on-paper with a hairline,
   drop the dark scrim entirely. Toggled by script.js's section observer. */
.topbar.zone-light { background: color-mix(in oklab, var(--paper) 92%, transparent); border-bottom: 1px solid var(--hairline-on-white); }
.topbar.zone-light::before, .topbar.zone-light::after { opacity: 0 !important; }
.topbar.zone-light .topbar__contact { color: var(--ink-on-white); border-bottom-color: color-mix(in oklab, var(--ink-on-white) 40%, transparent); }
.topbar.zone-light .topbar__label { color: var(--ink-soft-on-white); }
.topbar.zone-light .topbar__mark-img--white { opacity: 0; }
.topbar.zone-light .topbar__mark-img--black { opacity: 1; }

.topbar__mark { pointer-events: auto; line-height: 0; position: relative; display: block; width: 112px; height: 22px; }
.topbar__mark-img { height: 20px; width: auto; filter: drop-shadow(0 1px 3px rgba(0,0,0,0.4)); position: absolute; inset: 0; transition: opacity 300ms var(--sc-ease-out, ease); }
.topbar__mark-img--black { opacity: 0; filter: none; }
.topbar__contact {
  pointer-events: auto;
  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
  color: var(--sc-ink); text-decoration: none;
  border-bottom: 1px solid color-mix(in oklab, var(--sc-ink) 40%, transparent);
  transition: color 150ms ease, border-color 150ms ease;
  /* scroll_verify.py mätte 3.66:1 (golv 4.5) mot skymningsfotots ljusa
     himmel: den bakomliggande skrimmen räcker inte överallt. En mjuk
     textskugga håller kontrasten även över de ljusaste molnen, utan att
     ändra skrimmen som täcker resten av bilden. */
  text-shadow: 0 1px 4px rgba(0,0,0,0.7), 0 1px 1px rgba(0,0,0,0.5);
}
.topbar.zone-light .topbar__contact { text-shadow: none; }
.topbar__contact:hover { border-bottom-color: var(--sc-accent); color: var(--sc-accent); }
.topbar__label {
  font-family: var(--sc-font-text); font-size: var(--sc-t-xs);
  letter-spacing: var(--sc-track-wide); text-transform: uppercase;
  color: var(--sc-ink-soft); opacity: 0; white-space: nowrap;
  position: absolute; left: 50%; translate: -50% 0;
  transition: color 300ms var(--sc-ease-out, ease);
}
@media (max-width: 860px) { .topbar__label { display: none; } }

/* ------------------------------------------------------- reservläge/motion toggle -- */
.motion-only { display: none; }
html.motion .motion-only { display: block; }
html.motion .rm-only { display: none; }
.rm-only { display: block; }

/* ------------------------------------------------------ akt 1-4a signatur -- */
.sig-stage { background: var(--sc-canvas); overflow: clip; }

/* Fas 1 (p 0-0.46): kameraresan, ritad själv på canvasen. Fas "fortsatt zoom"
   (p 0.46-0.50): hela lagret (foto + fönstermask) skalas tillsammans med en
   CSS-transform, ursprung satt av script.js till fönstrets mittpunkt vid sista
   rutan. Fas "bytet" (p 0.50-0.52): lagret tonar bort medan den riktiga ramen
   tonar in -- samma bro-tekniker (oskärpa vid korstoningen) som runda 3, nu
   smalare fönster (0,02 i stället för 0,35 av den gamla akten) per denna
   rundas exakta faströrelser. */
.sig-photo-layer {
  position: absolute; inset: 0;
  --zoom2: clamp(0, (var(--sc-p, 0) - 0.46) / 0.04, 1);
  --xfade1: clamp(0, (var(--sc-p, 0) - 0.50) / 0.02, 1);
  transform-origin: var(--sig-window-x, 50%) var(--sig-window-y, 50%);
  transform: scale(calc(1 + var(--zoom2) * 0.282));
  opacity: calc(1 - var(--xfade1));
  filter: blur(calc(4 * var(--xfade1) * (1 - var(--xfade1)) * 6px));
}
.window-glow, .window-fill, .window-glass {
  position: absolute; left: 0; top: 0; width: 0; height: 0;
  opacity: 0; z-index: 2; pointer-events: none;
}
.window-glow {
  background: radial-gradient(closest-side, color-mix(in oklab, var(--sc-accent) 85%, white) 0%, color-mix(in oklab, var(--sc-accent) 40%, transparent) 60%, transparent 100%);
}
.window-fill { object-fit: cover; display: block; }
.window-glass { overflow: hidden; mix-blend-mode: multiply; }
.window-glass__canvas { width: 100%; height: 100%; display: block; }
.sig-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.hero-copy {
  filter: blur(calc(min(var(--sc-p, 0), 0.3) * 46.67px));
}
.hero-title {
  font-weight: 300; font-size: clamp(2.2rem, 3.4rem + 1.6vw, 5.5rem);
  line-height: 1.05; letter-spacing: -0.01em; color: var(--sc-ink);
  max-width: 16ch;
}
.accent-u { text-decoration: underline; text-decoration-color: var(--sc-accent); text-decoration-thickness: 2px; text-underline-offset: 0.1em; }
/* scroll_verify.py flaggade denna som en cue som aldrig når full opacitet
   (peak 0.86) -- opaciteten var en smaksak (en "tystare" underrad), inte en
   avsiktlig cue-gräns, och håller inte isär de två. Dämpningen sker nu genom
   en egen ton i stället, så cuen faktiskt kan nå 1. */
.hero-sub { color: var(--sc-ink); margin-top: var(--sc-4); font-size: var(--sc-t-lg); }

.site-names {
  position: absolute; left: var(--sc-gutter); bottom: clamp(1.25rem, 4vh, 2.5rem);
  z-index: 5; margin: 0;
  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
  letter-spacing: var(--sc-track-normal); color: var(--sc-ink-soft);
}
.site-names--static { position: static; margin-top: var(--sc-6); color: var(--sc-ink-soft); }

