  font-size: clamp(2rem, 1.4rem + 3.6vw, 4.5rem); line-height: 1.16;
}
/* Ä:s prickar sitter ovanför versalhöjden och kapas av motorns
   .sc-split--line-mask (overflow:hidden) vid en trång line-height -- exakt
   samma fel r6 en gång rättade ("VARUMÄRKE" tappade prickarna). Fixen är
   densamma: luft ovanför masken, aldrig overflow borttaget (motorklassen
   rörs inte). */
.exit-heading .sc-split--line { padding-top: 0.16em; margin-top: -0.16em; }
.exit-lede { font-family: var(--sc-font-text); font-size: var(--sc-t-lg); color: var(--ink-soft-on-white); margin-top: var(--sc-4); max-width: 40ch; }
