        var vis = 0;
        if (p >= 0.54 && p <= 0.68) {
          var win = 0.68 - 0.54;
          var inEnd = 0.54 + win * 0.3, outStart = 0.68 - win * 0.3;
          if (p < inEnd) vis = smooth((p - 0.54) / (inEnd - 0.54));
