    var zoneEls = document.querySelectorAll('[data-topbar-zone]');
    if ('IntersectionObserver' in window && zoneEls.length) {
      var zoneIO = new IntersectionObserver(function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
